import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;
import java.util.Locale;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int t = scanner.nextInt();
        int n = scanner.nextInt();

        double[] x = new double[n];
        for (int i = 0; i < n; i++) {
            x[i] = scanner.nextInt();
        }

        Arrays.sort(x);

        double minLength = Double.MAX_VALUE;

        // Primeira cidade
        double firstLength = (x[0] + x[1]) / 2.0;
        minLength = Math.min(minLength, firstLength);

        // Cidades intermediárias
        for (int i = 1; i < n - 1; i++) {
            double length = (x[i + 1] - x[i - 1]) / 2.0;
            minLength = Math.min(minLength, length);
        }

        // Última cidade
        double lastLength = t - (x[n - 2] + x[n - 1]) / 2.0;
        minLength = Math.min(minLength, lastLength);

        System.out.printf(Locale.US, "%.2f\n", minLength);
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
